Here is a basic C++ program using the popular **OpenCV** library to perform facial detection using a Haar Cascade classifier. 

### Prerequisites:
You will need to have OpenCV installed on your system and have the `haarcascade_frontalface_default.xml` file (which comes with OpenCV) in your project directory.

### C++ Code:
```cpp
#include <opencv2/opencv.hpp>
#include <iostream>

using namespace cv;
using namespace std;

int main() {
    // Load the pre-trained Haar Cascade classifier for face detection
    CascadeClassifier faceCascade;
    if (!faceCascade.load("haarcascade_frontalface_default.xml")) {
        cout << "Error: Could not load classifier cascade." << endl;
        return -1;
    }

    // Open the default camera (use 0 for default, or a video file path)
    VideoCapture cap(0);
    if (!cap.isOpened()) {
        cout << "Error: Could not open video stream." << endl;
        return -1;
    }

    Mat frame, grayFrame;
    cout << "Press 'ESC' to exit..." << endl;

    while (true) {
        // Capture frame-by-frame
        cap >> frame;
        if (frame.empty()) break;

        // Convert the frame to grayscale for the detector
        cvtColor(frame, grayFrame, COLOR_BGR2GRAY);
        equalizeHist(grayFrame, grayFrame);

        // Detect faces
        vector<Rect> faces;
        faceCascade.detectMultiScale(grayFrame, faces, 1.1, 3, 0, Size(30, 30));

        // Draw a rectangle around each detected face
        for (size_t i = 0; i < faces.size(); i++) {
            rectangle(frame, faces[i], Scalar(255, 0, 0), 2);
        }

        // Display the resulting frame
        imshow("Face Detection", frame);

        // Break the loop if the user presses the 'ESC' key
        if (waitKey(10) == 27) {
            break;
        }
    }

    return 0;
}
```

