    HWND hwnd = GetDesktopWindow();
    HDC hwindowDC = GetDC(hwnd);
    HDC hwindowCompatibleDC = CreateCompatibleDC(hwindowDC);

    // 2. Determine screen dimensions
    width = GetSystemMetrics(SM_CXSCREEN);
