    bi.biHeight = -height; // Negative indicates a top-down Device-Independent Bitmap (DIB)
    bi.biPlanes = 1;
    bi.biBitCount = 32;    // 32 bits per pixel (RGBA)
    bi.biCompression = BI_RGB;

    // 6. Resize the buffer to hold the pixel data (Width * Height * 4 bytes)
    pixelBuffer.resize(width * height * 4);

    // 7. Extract the bits into the vector buffer
    GetDIBits(hwindowCompatibleDC, hbwindow, 0, height, pixelBuffer.data(), (BITMAPINFO*)&bi, DIB_RGB_COLORS);

    // 8. Clean up resources to prevent memory leaks
    DeleteObject(hbwindow);
    DeleteDC(hwindowCompatibleDC);
    ReleaseDC(hwnd, hwindowDC);

    return true;
}
