// Structure to hold a single calibration point
typedef struct {
    uint16_t adc_raw;   // X-axis: Raw ADC reading (e.g., 0 to 4095 for 12-bit)
    float    real_val;  // Y-axis: Calibrated value (e.g., Voltage, Temperature)
} CalPoint_t;

// Example Calibration Table (MUST be sorted in ascending order of adc_raw)
// For example: mapping a 12-bit ADC (0-4095) to 0.0V - 5.0V with non-linearities
const CalPoint_t CalibrationTable[NUM_CAL_POINTS] = {
    { 10,   0.00 }, // Point 0 (Offset)
    { 400,  0.50 }, // Point 1
    { 820,  1.00 }, // Point 2
    { 1235, 1.50 }, // Point 3
    { 1650, 2.00 }, // Point 4
    { 2048, 2.50 }, // Point 5 (Midpoint)
    { 2460, 3.00 }, // Point 6
    { 2870, 3.50 }, // Point 7
    { 3280, 4.00 }, // Point 8
    { 3690, 4.50 }, // Point 9
    { 4080, 5.00 }  // Point 10 (Full scale)
};

/**
 * @brief Converts a raw ADC value to a calibrated value using linear interpolation
 * @param raw_adc The raw value read from the ADC register
 * @return The calibrated floating-point value
 */
float interpolate_adc(uint16_t raw_adc) {
    // 1. Out-of-bounds Handling (Clamping)
    // If ADC is below our lowest calibration point, return the lowest real value
    if (raw_adc <= CalibrationTable[0].adc_raw) {
        return CalibrationTable[0].real_val;
    }
    // If ADC is above our highest calibration point, return the highest real value
    if (raw_adc >= CalibrationTable[NUM_CAL_POINTS - 1].adc_raw) {
        return CalibrationTable[NUM_CAL_POINTS - 1].real_val;
    }

    // 2. Find the correct interval for interpolation
    for (int i = 0; i < NUM_CAL_POINTS - 1; i++) {

        uint16_t x0 = CalibrationTable[i].adc_raw;
        uint16_t x1 = CalibrationTable[i + 1].adc_raw;

        // Check if our raw_adc falls between point i and point i+1
        if (raw_adc >= x0 && raw_adc <= x1) {

            float y0 = CalibrationTable[i].real_val;
            float y1 = CalibrationTable[i + 1].real_val;

            // Protection against divide-by-zero if calibration data is bad (x0 == x1)
            if (x1 == x0) {
                return y0; 
            }

            // 3. Linear Interpolation Formula: y = y0 + (x - x0) * ((y1 - y0) / (x1 - x0))
            float interpolated_val = y0 + ((float)(raw_adc - x0) * (y1 - y0) / (float)(x1 - x0));

            return interpolated_val;
        }
    }

    // Should never reach here due to bounds checking, but return 0 as a fallback
    return 0.0f; 
}

int main() {
    // Test cases
    uint16_t test_adcs[] = { 5, 10, 400, 1000, 2048, 3000, 4080, 4095 };

    printf("ADC Raw\t-> Calibrated Value\n");
    printf("---------------------------\n");

    for(int i = 0; i < 8; i++) {
        float result = interpolate_adc(test_adcs[i]);
        printf("%d\t-> %.3f\n", test_adcs[i], result);
    }

    return 0;
}
```

### Important rules for this to work:
1. **Ascending Order:** The `CalibrationTable` **must** be sorted from the lowest ADC value to the highest. If it is not sorted, the `for` loop will not find the correct interval.
2. **Clamping vs. Extrapolation:** This code uses *clamping*. If your ADC reads `4095` but your highest calibration point is `4080`, the code returns `5.00`. It will not guess what `4095` is. This is usually the safest approach for embedded systems to prevent erratic behaviors at the extremes.

### Integer-Only Alternative (For 8-bit/16-bit MCUs without FPU)
If your microcontroller does not have a Floating Point Unit (FPU), floating-point math can be very slow. You can use fixed-point math by multiplying your real values by `1000` (e.g., `5.00V` becomes `5000mV`).

Here is how the calculation changes for integer math:
```c
// Assuming y0, y1 are now integers (e.g. millivolts)
int32_t y0 = CalibrationTable[i].real_val_mv;
int32_t y1 = CalibrationTable[i + 1].real_val_mv;

// Note: Multiply before dividing to prevent integer truncation!
int32_t interpolated_val = y0 + (((int32_t)(raw_adc - x0) * (y1 - y0)) / (int32_t)(x1 - x0));
```

Here is a complete, production-ready C implementation for an 11-point linear interpolation. 

This code uses a Lookup Table (LUT) to map raw ADC readings to calibrated real-world values (like Voltage, Temperature, or corrected ADC counts).

### The C Code

```c
#include <stdio.h>
#include <stdint.h>

#define NUM_CAL_POINTS 11

// Structure to hold a single calibration point
typedef struct {
    uint16_t raw_adc;    // The X value (what the ADC actually reads)
    float    true_value; // The Y value (the actual physical value, e.g., voltage)
} CalibrationPoint;

// 11-Point Calibration Table
// IMPORTANT: The raw_adc values MUST be in strictly ascending order!
const CalibrationPoint adc_cal_table[NUM_CAL_POINTS] = {
    { 100,  0.10 }, // Point 1
    { 500,  0.45 }, // Point 2
    { 900,  0.80 }, // Point 3
    { 1300, 1.20 }, // Point 4
    { 1700, 1.65 }, // Point 5
    { 2100, 2.05 }, // Point 6
    { 2500, 2.45 }, // Point 7
    { 2900, 2.80 }, // Point 8
    { 3300, 3.10 }, // Point 9
    { 3700, 3.25 }, // Point 10
    { 4000, 3.30 }  // Point 11
};

/**
 * @brief Performs linear interpolation based on the calibration table.
 * 
 * @param raw_input The raw ADC value to be calibrated.
 * @param table     Pointer to the calibration table.
 * @return float    The calibrated value.
 */
float interpolate_adc(uint16_t raw_input, const CalibrationPoint* table) {
    // 1. Handle Out-of-Bounds (Clamping to lowest value)
    if (raw_input <= table[0].raw_adc) {
        return table[0].true_value;
    }

    // 2. Handle Out-of-Bounds (Clamping to highest value)
    if (raw_input >= table[NUM_CAL_POINTS - 1].raw_adc) {
        return table[NUM_CAL_POINTS - 1].true_value;
    }

    // 3. Find the correct segment and interpolate
    for (int i = 0; i < NUM_CAL_POINTS - 1; i++) {
        if (raw_input >= table[i].raw_adc && raw_input <= table[i+1].raw_adc) {

            float x0 = (float)table[i].raw_adc;
            float x1 = (float)table[i+1].raw_adc;
            float y0 = table[i].true_value;
            float y1 = table[i+1].true_value;

            // Prevent division by zero if table is configured incorrectly
            if (x1 == x0) {
                return y0; 
            }

            // Linear Interpolation Formula: y = y0 + (x - x0) * ((y1 - y0) / (x1 - x0))
            float calibrated_value = y0 + ((float)raw_input - x0) * ((y1 - y0) / (x1 - x0));

            return calibrated_value;
        }
    }

    // Should never reach here if the table is sorted properly
    return 0.0f; 
}

// --- Test / Example Usage ---
int main() {
    // Array of test ADC values to simulate reading from hardware
    uint16_t test_readings[] = { 50, 100, 700, 2100, 2300, 3900, 4095 };
    int num_tests = sizeof(test_readings) / sizeof(test_readings[0]);

    printf("Raw ADC\t|\tCalibrated Value\n");
    printf("--------------------------------\n");

    for (int i = 0; i < num_tests; i++) {
        uint16_t raw = test_readings[i];
        float calibrated = interpolate_adc(raw, adc_cal_table);
        printf("%u\t|\t%.3f\n", raw, calibrated);
    }

    return 0;
}
```

### How it Works:
1. **The Data Structure:** We define a `CalibrationPoint` struct. `raw_adc` is the $X$ axis, and `true_value` is the $Y$ axis. 
2. **Bounds Checking (Clamping):** If the ADC reads a value lower than your first calibration point or higher than your last, the code "clamps" the output to the lowest or highest known true value. This prevents wild calculations at the extremes.
3. **Linear Search:** Because 11 points is a very small array, a simple `for` loop is the most efficient way to find which two points your raw ADC reading falls between. *(Note: If you had 100+ points, a binary search would be better, but for 11 points, a `for` loop is actually faster due to less branching overhead).*
4. **The Math:** Once it finds the two points (let's call them $P_0$ and $P_1$), it applies the standard linear interpolation formula: 
   $$Y = Y_0 + (X - X_0) \times \frac{Y_1 - Y_0}{X_1 - X_0}$$

### Important Considerations for your specific project:

* **Sorting is Mandatory:** The `raw_adc` values in your `adc_cal_table` **must** go from lowest to highest. If they are out of order, the algorithm will fail.
* **Integer vs Float:** If you are running this on an 8-bit microcontroller (like an AVR/Arduino) without a Hardware Floating-Point Unit (FPU), using `float` will be slow. If performance is critical on a small MCU, you should scale your true values by 1000 (e.g., 3.3V becomes `3300`) and do the math entirely using `int32_t`.
* **Extrapolation vs Clamping:** If your ADC reads `4095`, but your highest calibration point is `4000`, this code returns the value for `4000`. If you want it to mathematically guess the value for `4095` based on the slope of the last two points (Extrapolation), you would remove the bounds checking at the top of the function. For ADCs, clamping is usually safer.

While the default `[Header("Text")]` attribute in Unity cannot be collapsed natively, there are a few excellent ways to achieve collapsible sections to keep your Inspector clean. 

Here are the best methods, ranging from built-in Unity solutions to popular free plugins:

### Method 1: The Built-in Way (Serializable Classes/Structs)
The easiest way to create a collapsible header without downloading any plugins is to group your variables into a `[System.Serializable]` class or struct. Unity automatically draws these as collapsible foldouts in the Inspector.

**How to do it:**
```csharp
using UnityEngine;

public class MyScript : MonoBehaviour
{
    // 1. Define a class or struct and mark it as Serializable
    [System.Serializable]
    public struct MovementSettings
    {
        public float walkSpeed;
        public float runSpeed;
        public float jumpForce;
    }

    [System.Serializable]
    public struct CombatSettings
    {
        public int health;
        public int damage;
    }

    // 2. Create variables of these types
    // The names of these variables will become your collapsible headers!
    public MovementSettings movement;
    public CombatSettings combat;
}
```

### Method 2: The Free Plugin Way (NaughtyAttributes)
If you want to keep all your variables loose in the main script but still group them under collapsible headers, the standard practice in the Unity community is to use a free, open-source library called **NaughtyAttributes**. 

1. Download it for free from the Unity Asset Store or GitHub.
2. Add `using NaughtyAttributes;` to the top of your script.
3. Use the `[Foldout]` attribute.

**How to do it:**
```csharp
using UnityEngine;
using NaughtyAttributes; // Add this

public class MyScript : MonoBehaviour
{
    [Foldout("Movement Settings")]
    public float walkSpeed;

    [Foldout("Movement Settings")]
    public float runSpeed;

    [Foldout("Combat Settings")]
    public int health;

    [Foldout("Combat Settings")]
    public int damage;
}
```

### Method 3: The Premium Way (Odin Inspector)
If you are working on a larger project or a professional team, the industry standard for Inspector customization is a paid asset called **Odin Inspector**. It works similarly to NaughtyAttributes but is much more powerful. You would use `[FoldoutGroup("Group Name")]` to achieve this.

